import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    flights = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(m)]

    graph = defaultdict(list)
    for a, b in flights:
        graph[a].append(b)

    def bfs_shortest_path(graph, start, end):
        queue = deque([(start, [])])
        visited = set()
        while queue:
            node, path = queue.popleft()
            if node == end:
                return path
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    queue.append((neighbor, path + [neighbor]))
        return None

    def find_all_paths(graph, start, end, path=[]):
        path = path + [start]
        if start == end:
            return [path]
        paths = []
        for node in graph[start]:
            if node not in path:
                newpaths = find_all_paths(graph, node, end, path)
                for newpath in newpaths:
                    paths.append(newpath)
        return paths

    all_paths = find_all_paths(graph, 1, n)
    if not all_paths:
        print("No")
        return

    min_length = min(len(p) for p in all_paths)
    max_length = max(len(p) for p in all_paths)
    if max_length - min_length > 1:
        print("No")
        return

    path_durations = {tuple(path): [1] * (len(path) - 1) for path in all_paths}
    for path in all_paths:
        if len(path) == min_length:
            continue
        for i in range(len(path) - 1):
            path_durations[tuple(path)][i] = 2

    chosen_path = all_paths[0]
    durations = path_durations[tuple(chosen_path)]
    flight_to_duration = {}
    for i in range(len(chosen_path) - 1):
        flight = (chosen_path[i], chosen_path[i + 1])
        flight_to_duration[flight] = durations[i]

    print("Yes")
    for a, b in flights:
        print(flight_to_duration[(a, b)])

main()
